import os
import subprocess

def git_clone(repo_url):
    try:
        subprocess.run(['git', 'clone', repo_url], check=True, capture_output=True)
        print(f"Repository cloned successfully from {repo_url}")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error cloning repository: {e.stderr.decode()}")
        return False

def create_branch(branch_name, start_point="main"):
    try:
        subprocess.run(['git', 'checkout', '-b', branch_name, start_point], check=True, capture_output=True)
        print(f"Created and checked out branch: {branch_name}")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error creating/checking out branch: {e.stderr.decode()}")
        return False

def fetch_issue(owner, repo, issue_number):
    try:
        command = ['curl', '-s', f'https://api.github.com/repos/{owner}/{repo}/issues/{issue_number}']
        result = subprocess.run(command, check=True, capture_output=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error fetching issue: {e.stderr.decode()}")
        return None
